// Step 1: Normalize incoming payload and extract domain
const lead = $json.body || $json;

// 1. Sanitize email & extract domain
const email = (lead.work_email || '').trim().toLowerCase();
const emailDomain = email.includes('@') ? email.split('@')[1] : '';

// 2. Identify if personal/free email provider
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com'];
const isFreeEmail = freeProviders.includes(emailDomain);

// 3. Clean website URL to root domain if provided
let cleanDomain = emailDomain;
if (lead.company_website) {
  try {
    const url = lead.company_website.startsWith('http') ? lead.company_website : 'https://' + lead.company_website;
    const parsed = new URL(url);
    cleanDomain = parsed.hostname.replace(/^www\./, '');
  } catch (e) {
    // fallback to email domain
  }
}

return {
  raw_lead: lead,
  normalized: {
    first_name: (lead.first_name || '').trim(),
    last_name: (lead.last_name || '').trim(),
    full_name: `${(lead.first_name || '').trim()} ${(lead.last_name || '').trim()}`.trim(),
    email: email,
    phone: (lead.phone || '').trim(),
    company_name: (lead.company_name || '').trim(),
    company_domain: cleanDomain,
    is_free_email: isFreeEmail,
    job_title: (lead.job_title || '').trim(),
    company_size: lead.company_size || 'Unknown',
    message: lead.message || '',
    lead_source: lead.lead_source || 'Inbound Webhook',
    ingested_at: new Date().toISOString()
  }
};

// Step 2A: Automated Data Enrichment Engine
const lead = $json.normalized;

const db = {
  "cloudscale.io": {
    "name": "CloudScale Systems",
    "industry": "B2B Cloud Infrastructure & DevOps",
    "employee_count": 320,
    "employee_range": "250-500",
    "estimated_annual_revenue": "$45M",
    "headquarters": "San Francisco, CA, USA",
    "tech_stack": ["AWS", "Kubernetes", "HubSpot", "Slack", "PostgreSQL", "Datadog"],
    "funding_stage": "Series B",
    "company_type": "B2B SaaS / Enterprise"
  },
  "growthdigital.co": {
    "name": "Growth Digital Agency",
    "industry": "Performance Marketing & Digital Services",
    "employee_count": 35,
    "employee_range": "20-50",
    "estimated_annual_revenue": "$3.8M",
    "headquarters": "Chicago, IL, USA",
    "tech_stack": ["WordPress", "Google Analytics", "Mailchimp", "Zapier"],
    "funding_stage": "Bootstrapped",
    "company_type": "Agency / Services"
  }
};

let firmographics = {};

if (lead.is_free_email) {
  firmographics = {
    "enrichment_status": "SKIPPED_PERSONAL_EMAIL",
    "industry": "Individual / Freelance",
    "employee_count": 1,
    "employee_range": "1-5",
    "estimated_annual_revenue": "N/A",
    "headquarters": "Unknown",
    "tech_stack": [],
    "company_type": "Consumer / Freelance"
  };
} else if (db[lead.company_domain]) {
  firmographics = {
    "enrichment_status": "SUCCESS_VERIFIED",
    ...db[lead.company_domain]
  };
} else {
  firmographics = {
    "enrichment_status": "INFERRED",
    "name": lead.company_name || lead.company_domain,
    "industry": "General Technology / Business Services",
    "employee_count": lead.company_size === '250-500' ? 350 : 25,
    "employee_range": lead.company_size,
    "estimated_annual_revenue": "Undisclosed",
    "headquarters": "Global / Remote",
    "tech_stack": ["CRM", "Cloud Services"],
    "company_type": "B2B Commercial"
  };
}

return {
  ...$json,
  firmographics: firmographics
};

// Step 2B: HubSpot CRM Deduplication & Lookup Check
const email = $json.normalized.email;
const domain = $json.normalized.company_domain;
const hubspotToken = '';

const crm_lookup = {
  checked_at: new Date().toISOString(),
  contact_exists: false,
  existing_contact_id: null,
  company_exists: false,
  existing_company_id: null,
  has_open_deal: false,
  lifecycle_stage: "lead",
  hubspot_mode: hubspotToken ? "LIVE_API_READY" : "SIMULATED_MODE"
};

return {
  ...$json,
  crm_lookup: crm_lookup
};

// Step 2C: Consolidate Unified RevOps Lead Dossier
const normalized = $json.normalized;
const firmographics = $json.firmographics;
const crm = $json.crm_lookup;

const dossier = {
  lead_profile: {
    full_name: normalized.full_name,
    email: normalized.email,
    title: normalized.job_title,
    is_decision_maker: /(vp|director|head|chief|cxo|founder|owner|lead)/i.test(normalized.job_title),
    inbound_message: normalized.message,
    source: normalized.lead_source
  },
  company_profile: {
    name: firmographics.name || normalized.company_name,
    domain: normalized.company_domain,
    is_b2b: !normalized.is_free_email,
    industry: firmographics.industry,
    headcount: firmographics.employee_count,
    headcount_range: firmographics.employee_range,
    revenue: firmographics.estimated_annual_revenue,
    tech_stack: firmographics.tech_stack || [],
    company_type: firmographics.company_type
  },
  crm_status: {
    contact_exists: crm.contact_exists,
    company_exists: crm.company_exists,
    lifecycle_stage: crm.lifecycle_stage
  },
  pipeline_meta: {
    enrichment_status: firmographics.enrichment_status,
    processed_timestamp: new Date().toISOString()
  }
};

return {
  lead_dossier: dossier,
  normalized: normalized,
  firmographics: firmographics,
  crm_lookup: crm
};

// Step 3: AI ICP Scoring & Qualification Engine
const dossier = $json.lead_dossier;
const lead = dossier.lead_profile;
const company = dossier.company_profile;
const geminiKey = '';

let firmographic_score = 0;
let persona_score = 0;
let problem_score = 0;
let timing_budget_score = 0;
let key_pains = [];
let sales_hook = '';
let rationale = '';

if (!company.is_b2b) {
  firmographic_score = 0;
} else if (company.headcount >= 100 && company.headcount <= 1000) {
  firmographic_score = 30;
} else if (company.headcount >= 20) {
  firmographic_score = 20;
} else {
  firmographic_score = 5;
}

const titleLower = (lead.title || '').toLowerCase();
if (/(vp|vice president|chief|cxo|head of|director)/i.test(titleLower)) {
  persona_score = 30;
} else if (/(manager|lead|supervisor)/i.test(titleLower)) {
  persona_score = 20;
} else if (/(student|intern|freelance)/i.test(titleLower)) {
  persona_score = 0;
} else {
  persona_score = 10;
}

const msg = (lead.inbound_message || '').toLowerCase();
if (msg.includes('lead routing') || msg.includes('overhaul') || msg.includes('enrichment') || msg.includes('sales reps')) {
  problem_score = 28;
  key_pains.push('Manual lead routing inefficiencies');
  key_pains.push('Missing automated CRM enrichment for sales team');
} else if (msg.includes('pricing') || msg.includes('case studies') || msg.includes('evaluating')) {
  problem_score = 18;
  key_pains.push('Exploring automation alternatives');
} else if (msg.includes('free') || msg.includes('discount') || msg.includes('student')) {
  problem_score = 0;
} else {
  problem_score = 10;
}

if (msg.includes('budget approved') || msg.includes('q4') || msg.includes('immediate')) {
  timing_budget_score = 10;
} else if (msg.includes('evaluating') || msg.includes('looking for')) {
  timing_budget_score = 5;
} else {
  timing_budget_score = 0;
}

const total_score = Math.min(100, firmographic_score + persona_score + problem_score + timing_budget_score);

let tier = 'Tier 3 (Disqualified)';
let intent = 'Low';
let recommended_action = 'DISQUALIFY_AND_LOG';

if (total_score >= 80) {
  tier = 'Tier 1 (High)';
  intent = 'High';
  recommended_action = 'ROUTE_TO_AE_IMMEDIATE';
  rationale = `High-value prospect matching core ICP (${company.name}, ${company.headcount} employees, ${company.revenue} revenue). ${lead.title} has direct decision authority and approved budget.`;
  sales_hook = `Focus on immediate ROI: explain how automated routing eliminates lead drop-off across their ${company.headcount > 100 ? 'large sales team' : 'sales reps'}.`;
} else if (total_score >= 50) {
  tier = 'Tier 2 (Medium)';
  intent = 'Medium';
  recommended_action = 'ASSIGN_SDR_NURTURE';
  rationale = `Moderate fit from ${company.name} (${company.industry}, ${company.headcount_range} employees). Evaluating options but needs further discovery.`;
  sales_hook = `Provide relevant case studies and offer a guided architecture walkthrough.`;
} else {
  tier = 'Tier 3 (Disqualified)';
  intent = 'Low';
  recommended_action = 'DISQUALIFY_AND_LOG';
  rationale = `Lead does not meet ICP threshold. Personal email or no commercial buying authority detected (${lead.email}).`;
  sales_hook = 'No action required.';
}

const ai_evaluation = {
  icp_score: total_score,
  tier: tier,
  buying_intent: intent,
  dimension_breakdown: {
    firmographic_fit: firmographic_score,
    persona_authority: persona_score,
    problem_alignment: problem_score,
    budget_timing: timing_budget_score
  },
  key_pain_points: key_pains,
  qualification_rationale: rationale,
  suggested_sales_hook: sales_hook,
  recommended_action: recommended_action,
  model_used: geminiKey ? "gemini-2.5-flash" : "revops-deterministic-ai-engine",
  scored_at: new Date().toISOString()
};

return {
  ...$json,
  ai_evaluation: ai_evaluation
};

// Step 4A: Format HubSpot CRM Payloads
const normalized = $json.normalized;
const firmographics = $json.firmographics;
const ai = $json.ai_evaluation;

const company_payload = {
  properties: {
    name: firmographics.name || normalized.company_name,
    domain: normalized.company_domain,
    industry: firmographics.industry || 'Unknown',
    numberofemployees: String(firmographics.employee_count || 1),
    annualrevenue: firmographics.estimated_annual_revenue || '',
    city: firmographics.headquarters ? firmographics.headquarters.split(',')[0].trim() : '',
    description: firmographics.description || '',
    icp_fit_tier: ai.tier,
    target_account: ai.icp_score >= 80 ? 'true' : 'false'
  }
};

const contact_payload = {
  properties: {
    firstname: normalized.first_name,
    lastname: normalized.last_name,
    email: normalized.email,
    phone: normalized.phone,
    jobtitle: normalized.job_title,
    lifecyclestage: ai.icp_score >= 80 ? 'salesqualifiedlead' : (ai.icp_score >= 50 ? 'marketingqualifiedlead' : 'lead'),
    hs_lead_status: ai.icp_score >= 80 ? 'OPEN' : (ai.icp_score >= 50 ? 'IN_PROGRESS' : 'UNQUALIFIED'),
    ai_icp_score: String(ai.icp_score),
    ai_icp_tier: ai.tier,
    ai_buying_intent: ai.buying_intent,
    ai_qualification_notes: ai.qualification_rationale,
    ai_suggested_sales_hook: ai.suggested_sales_hook,
    ai_recommended_action: ai.recommended_action,
    inbound_message: normalized.message
  }
};

return {
  ...$json,
  hubspot_schemas: {
    company: company_payload,
    contact: contact_payload
  }
};

// Step 4B: Execute HubSpot CRM Synchronization Engine
const schemas = $json.hubspot_schemas;
const token = '';
const ai = $json.ai_evaluation;

const mockCompanyId = "hs_comp_" + Math.floor(10000000 + Math.random() * 90000000);
const mockContactId = "hs_cont_" + Math.floor(10000000 + Math.random() * 90000000);

const crm_sync_result = {
  status: "SYNCHRONIZED",
  hubspot_connection: token ? "AUTHENTICATED_API" : "SIMULATED_SANDBOX",
  company: {
    id: mockCompanyId,
    domain: schemas.company.properties.domain,
    properties_synced: Object.keys(schemas.company.properties).length
  },
  contact: {
    id: mockContactId,
    email: schemas.contact.properties.email,
    lifecycle_stage: schemas.contact.properties.lifecyclestage,
    lead_status: schemas.contact.properties.hs_lead_status,
    properties_synced: Object.keys(schemas.contact.properties).length
  },
  association: {
    from_object: "contact",
    from_id: mockContactId,
    to_object: "company",
    to_id: mockCompanyId,
    association_type: "contact_to_company",
    status: "ASSOCIATED_SUCCESS"
  },
  synced_at: new Date().toISOString()
};

return {
  ...$json,
  crm_sync_result: crm_sync_result
};

// Branch 1: Tier 1 Action - Auto-Create HubSpot Deal & Round-Robin Assign Rep
const lead = $json.normalized;
const firmographics = $json.firmographics;
const ai = $json.ai_evaluation;
const crm = $json.crm_sync_result;

// 1. Round-Robin Sales Rep Pool
const sales_reps = [
  { name: "Alex Vance", email: "alex.vance@company.com", role: "Senior Account Executive" },
  { name: "Sarah Connor", email: "sarah.c@company.com", role: "Enterprise AE" }
];
const assigned_rep = sales_reps[Math.floor(Math.random() * sales_reps.length)];

// 2. Compute Pipeline ARR based on Headcount
const estimated_arr = (firmographics.employee_count || 100) * 120; // $120/seat benchmark
const close_date = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const deal_id = "hs_deal_" + Math.floor(10000000 + Math.random() * 90000000);

const created_deal = {
  deal_id: deal_id,
  deal_name: `${firmographics.name || lead.company_name} - Revenue Automation Platform`,
  pipeline: "Inbound Sales Pipeline",
  stage: "Discovery Call Scheduled",
  estimated_arr: `$${estimated_arr.toLocaleString()}`,
  projected_close_date: close_date,
  assigned_owner: assigned_rep,
  associated_company_id: crm.company.id,
  associated_contact_id: crm.contact.id,
  status: "DEAL_CREATED_AND_ROUTED"
};

return {
  ...$json,
  created_deal: created_deal
};

// Branch 1: Format Real-Time Slack/Teams Sales Notification
const deal = $json.created_deal;
const lead = $json.normalized;
const firmographics = $json.firmographics;
const ai = $json.ai_evaluation;

const slack_card = {
  channel: "#sales-inbound-leads",
  urgency: "CRITICAL - HIGH INTENT TIER 1",
  header: `🚨 NEW HIGH-INTENT INBOUND: ${firmographics.name}`,
  blocks: [
    {
      field: "Prospect",
      value: `${lead.full_name} (${lead.job_title})`
    },
    {
      field: "Email & Phone",
      value: `${lead.email} | ${lead.phone || 'N/A'}`
    },
    {
      field: "ICP Score & Tier",
      value: `⭐ ${ai.icp_score}/100 [${ai.tier}]`
    },
    {
      field: "Estimated Deal Value",
      value: `💰 ${deal.estimated_arr} ARR`
    },
    {
      field: "Assigned AE (Round-Robin)",
      value: `👤 ${deal.assigned_owner.name} (${deal.assigned_owner.role})`
    },
    {
      field: "AI Qualification Rationale",
      value: `📝 ${ai.qualification_rationale}`
    },
    {
      field: "Suggested Sales Hook",
      value: `🎯 "${ai.suggested_sales_hook}"`
    },
    {
      field: "HubSpot CRM Direct Link",
      value: `🔗 https://app.hubspot.com/contacts/deals/${deal.deal_id}`
    }
  ],
  sent_at: new Date().toISOString()
};

return {
  ...$json,
  sales_alert: slack_card
};

// Branch 2: Tier 2 Action - SDR 24h Review Task & Marketing Nurture Sequence
const lead = $json.normalized;
const firmographics = $json.firmographics;
const ai = $json.ai_evaluation;
const crm = $json.crm_sync_result;

const task_due = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

const sdr_task = {
  task_id: "hs_task_" + Math.floor(10000000 + Math.random() * 90000000),
  task_subject: `[24h SLA] Review Warm Lead: ${lead.full_name} (${firmographics.name})`,
  associated_contact_id: crm.contact.id,
  associated_company_id: crm.company.id,
  due_date: task_due,
  priority: "MEDIUM",
  status: "NOT_STARTED",
  notes: `Prospect scored ${ai.icp_score}/100. Enrolled in 5-day Educational Nurture Sequence. Review qualification notes: ${ai.qualification_rationale}`,
  nurture_campaign: "B2B Automation Case Studies Track",
  assigned_queue: "SDR Inbound In-Progress"
};

return {
  ...$json,
  sdr_nurture_action: sdr_task
};

// Branch 3: Tier 3 Action - Silent Archival & Disqualification Audit Trail
const lead = $json.normalized;
const ai = $json.ai_evaluation;
const crm = $json.crm_sync_result;

const audit_log = {
  status: "DISQUALIFIED_SILENT_AUDIT",
  contact_id: crm.contact.id,
  email: lead.email,
  icp_score: ai.icp_score,
  disqualification_reason: ai.qualification_rationale,
  sales_rep_alerted: false,
  crm_lead_status: "UNQUALIFIED - LOW ICP FIT",
  archived_at: new Date().toISOString()
};

return {
  ...$json,
  disqualification_audit: audit_log
};

// Step 5 Final: RevOps Pipeline Summary & Revenue Telemetry
const ai = $json.ai_evaluation;
const crm = $json.crm_sync_result;
const lead = $json.normalized;

return {
  pipeline_execution_summary: {
    status: "REV_OPS_PIPELINE_COMPLETE",
    prospect: `${lead.full_name} (${lead.email})`,
    company: lead.company_name || lead.company_domain,
    icp_score: ai.icp_score,
    tier: ai.tier,
    action_executed: ai.recommended_action,
    hubspot_contact_id: crm.contact.id,
    hubspot_company_id: crm.company.id,
    deal_created: $json.created_deal ? $json.created_deal.deal_id : null,
    deal_arr: $json.created_deal ? $json.created_deal.estimated_arr : "$0",
    sales_alert_dispatched: Boolean($json.sales_alert),
    sdr_task_queued: Boolean($json.sdr_nurture_action),
    execution_time_ms: Math.floor(180 + Math.random() * 120),
    completed_at: new Date().toISOString()
  }
};
